    void best_pass_to_lie_low()
    {
        // Passing to lie low primarily involves handling bad spades: passing those dealt, and preparing to receive those mailed
        // Passes in priority order:
        // with QS in hand:
        // A1] suit_len_S = 1: QS
        // A2] suit_len_S <= 3: QS
        // A3] suit_len_S = 4 and pass_right: QS
        // A4] suit_len_S = 4: QS if rec'r is not low-scorer, CD voids = 0, CD singletons = 0, A/K/JS not in hand, not pass left
        // without QS in hand:
        // A5] AS, KS, or AKS: high S
        // A6] AKxS: AS, unless QS passed right (for AKQS see A2)
        // A7] AS, KS, AKS, AxS, or KxS and pass left: high S
        
        // without QS or with QS well-protected:
        // B1] twoC_leads and S <= 2 and small_C_suit: highest C
        // B2] suit_len_S <= 3: AKS (but not if passing QS right), S = 4: AKS (but not if passing QS right)
        
        // without further consideration of AKQS (except as mentioned)
        // 1] CD singleton (but not clubs if twoC_leads)
        // 2] H singleton >= 5
        // 2a] high in worst_suit if DoD >= 15
        // 2b] twoC_leads, QS neither in hand nor passed, A/KS, S <= 4, small_C_suit: highest C
        // 3] suit_len(CD) <= 4 and def_losers = 0: high card, smallest suit first
        // 3a] H doubleton and high H >= 10: high H
        // 5] <= 5 H with def_losers = 0
        // 6] suit_len(CD) <= 4 and def_losers < 2: high card, smallest suit first
        // 7] singleton heart when there is already a CDS void(s)
        // 8] CD doubleton with highest low card >= 5: D or C but if C and twoC_Leads then not AC
        // 9] H singleton >= 5
        // 9a] high in worst_suit if DoD >= 10
        // 10a] suit_len(CD) = 5 and def_losers < 2: high card, smallest suit first
        // 10b] with many S and QS and A/KS in hand: A/KS
        // 11] non-HU H iff all such can be passed
        // 12] suit_len(H) >= 2 and beatable H: if >= 5 H then 2nd-high H; same with 4 H if difference between high and 2nd-high
        // H <= 2, and with 3 H if difference = 1; else high H
        // 12a] singleton S: shortest CD (but not if passing QS right)
        // 13] no beatable H, no HU(H), and (high H > 7 or (high H > 5 and other H passed)): if >= 5 H then second_hi H, else high H
